(n, k) = map(int, input().split(' '))
c = list(map(int, input().split(' ')))
cost = 10000 * 1000000000
step = 2 * k + 1
if k == 0:
	ans = 0
	for i in c:
		ans += i
	print(ans)
else:
	for start in range(0, k + 1):
		remain = (n - 1 - start - k) % step
		if remain == 0 or remain > k:
			tmp_cost = 0
			for i in range(start, n + 1, step):
				tmp_cost += c[i]
				if tmp_cost > cost:
					break
			if tmp_cost < cost:
				cost = tmp_cost
	print(cost)
